<template>
  <div class="section-container profile-wrapper">
    <div class="id-badge hover-trigger">SUBJECT_01</div>
    <div class="level-text">LEVEL 7 OBSERVER</div>

    <!-- Generative Art Style Heatmap -->
    <div class="heatmap-grid hover-trigger" ref="heatmapRef">
      <!-- Cells will be generated by JavaScript -->
    </div>

    <div class="analysis-text">
      ANALYSIS COMPLETE.<br>
      DOMINANT TRAIT: <span class="trait-highlight">VISUAL_SEEKER</span>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'

const heatmapRef = ref(null)

onMounted(() => {
  if (heatmapRef.value) {
    // Generate heatmap cells
    for (let i = 0; i < 45; i++) {
      const div = document.createElement('div')
      const randomClass = `c-${Math.floor(Math.random() * 3) + 1}`
      const activeClass = Math.random() > 0.7 ? 'c-active' : ''
      div.className = `cell ${randomClass} ${activeClass}`
      heatmapRef.value.appendChild(div)
    }
  }
})
</script>

